  const publicApi={setLanguage,getLanguage:()=>currentLanguage,translate:value=>currentLanguage==="ar"?value:localizedTranslation(value,currentLanguage),t:(value,language=currentLanguage)=>language==="ar"?String(value??""):localizedTranslation(value,language),languages:null,ready};
  window.VAREXI18N=publicApi;window.VarexI18n=publicApi;
